WITH valid_suppliers AS (SELECT * FROM suppliers WHERE country IN ('JP', 'TH', 'DE') OR LENGTH(supplier_name) >= 14), summary AS (SELECT CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(rating) AS rating_count, SUM(rating) AS total_rating FROM valid_suppliers GROUP BY CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END) SELECT rating_bucket, rating_count, total_rating FROM summary WHERE rating_count < 3
